import React from "react";
import styles from "./deals.module.css";
import gift from "../../../assets/gift.png";

import mike from "../../../assets/mike.png";
import chat from "../../../assets/chat.png";
import live from "../../../assets/live.png";
const Deals = () => {
  const cardInfo = [
    {
      title: "Sign Up or Deposit Bonuses",
      description:
        "Get extra value and more opportunities to boost your poker bankroll right from the start!",
      img: gift,
    },
    {
      title: "Exclusive promotions",
      description:
        "Elevate Your Earnings with Exclusive Promotions: Rake Races and Points Races",
      img: mike,
    },
    {
      title: "Personal VIP Support",
      description:
        "Lorem ipsum dolor sit amet consectetur. Sapien scelerisque ut elit nunc nulla mi gravida eros. ",
      img: chat,
    },
    {
      title: "Chances at live Tournaments",
      description:
        "Lorem ipsum dolor sit amet consectetur. Sapien scelerisque ut elit nunc nulla mi gravida eros. ",
      img: live,
    },
  ];
  return (
    <div className={styles.deals_container}>
      {/* Content Section */}
      <div className={styles.content}>
        {/* Head Container */}
        <div className={styles.head_container}>
          <div className={styles.head}>
            {/* Head Content */}Our Rakeback Deals
          </div>
          <div className={styles.subhead}>
            {/* Subhead Content */}Beyond Monthly Boosts: Your Benefits with
            Rakeback.com
          </div>
        </div>

        {/* Deals Card Container */}
        <div className={styles.deals_card_container}>
          {/* Deals Card */}
          {cardInfo.map((deal) => {
            return (
              <div className={styles.deals_card}>
                {/* Card Content */}
                <div className={styles.card_content}>
                  {/* Text Container */}
                  <div className={styles.text_container}>
                    {/* Card Text Content */}
                    <div className={styles.card_text_content}>
                      {/* Title Container */}
                      <div className={styles.title_container}>
                        <div className={styles.title}>{deal.title}</div>
                        {/* Title Content */}
                      </div>
                      {/* Description Container */}
                      <div className={styles.description_container}>
                        <div className={styles.description}>
                          {deal.description}
                        </div>
                        {/* Description Content */}
                      </div>
                    </div>
                  </div>

                  {/* Learn More Container */}
                  <div className={styles.learn_more_container}>
                    {/* Text Content */}
                    <div className={styles.text}>
                      Learn More
                      {/* Icon Content */}
                    </div>
                    {/* <div className={styles.icon}> */}
                    {/* Icon */}
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="26"
                      height="12"
                      viewBox="0 0 26 12"
                      fill="none"
                    >
                      <path
                        d="M24 7.5C25.1046 7.5 26 8.39543 26 9.5C26 10.6046 25.1046 11.5 24 11.5L2 11.5C0.895429 11.5 -1.35705e-07 10.6046 -8.74228e-08 9.5C-3.91405e-08 8.39543 0.895432 7.5 2 7.5L24 7.5Z"
                        fill="#5C6077"
                      />
                      <path
                        d="M25.0711 7.74253C25.8522 8.52357 25.8522 9.7899 25.0711 10.571C24.2901 11.352 23.0238 11.352 22.2427 10.571L16.4143 4.74253C15.6332 3.96148 15.6332 2.69515 16.4143 1.9141C17.1953 1.13305 18.4617 1.13305 19.2427 1.9141L25.0711 7.74253Z"
                        fill="#5C6077"
                      />
                    </svg>
                    {/* </div> */}
                  </div>
                </div>

                {/* Image */}
                <div className={styles.image}>
                  {/* Image Content */}{" "}
                  <img src={deal.img} style={{ width: "100%" }} alt="" />{" "}
                </div>
              </div>
            );
          })}

          {/* Add more Deals Cards as needed */}
        </div>
      </div>
    </div>
  );
};

export default Deals;
